//! # platform-utils
//!
//! A library providing platform-aware utilities with clean conditional compilation.
//!
//! Uses `cfg-if` macros to define platform-specific behavior in a readable,
//! maintainable way across Linux, macOS, Windows, FreeBSD, and OpenBSD.

cfg_if::cfg_if! {
    if #[cfg(target_os = "linux")] {
        mod linux;
        pub use linux::*;
    } else if #[cfg(target_os = "macos")] {
        mod macos;
        pub use macos::*;
    } else if #[cfg(target_os = "windows")] {
        mod windows;
        pub use windows::*;
    } else if #[cfg(target_os = "freebsd")] {
        mod freebsd;
        pub use freebsd::*;
    } else if #[cfg(target_os = "openbsd")] {
        mod openbsd;
        pub use openbsd::*;
    } else {
        mod unknown;
        pub use unknown::*;
    }
}

/// Returns the name of the current platform.
pub fn platform_name() -> &'static str {
    platform_info().0
}

/// Returns platform-specific metadata as `(name, version_hint)`.
pub fn platform_info() -> (&'static str, &'static str) {
    unimplemented!("implementations exist per-target platform")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_platform_name() {
        let name = platform_name();
        assert!(!name.is_empty(), "platform name should not be empty");
    }
}

use std::sync::OnceLock;

static SYSTEM_INFO: OnceLock<(String, String)> = OnceLock::new();

fn get_system_info() -> &'static (String, String) {
    SYSTEM_INFO.get_or_init(|| {
        let mut info = [0i8; 64];
        let mut size = std::mem::size_of_val(&info);
        let mib = [1i32, 0i32]; // CTL_HW, HW_MACHINE_ARCH

        // Safety: libc call with valid pointers and sizes
        let ret = unsafe {
            libc::sysctl(
                mib.as_ptr(),
                mib.len() as u32,
                info.as_mut_ptr(),
                &mut size,
                std::ptr::null_mut(),
                0,
            )
        };

        if ret == 0 && size > 0 {
            let arch = unsafe {
                std::ffi::CStr::from_ptr(info.as_ptr() as *const std::ffi::c_char)
                    .to_string_lossy()
                    .to_string()
            };
            ("FreeBSD".to_string(), arch)
        } else {
            ("FreeBSD".to_string(), "unknown".to_string())
        }
    })
}

pub fn platform_info() -> (&'static str, &'static str) {
    let info = get_system_info();
    (&info.0, &info.1)
}

use std::sync::OnceLock;

static SYSTEM_INFO: OnceLock<(String, String)> = OnceLock::new();

fn get_system_info() -> &'static (String, String) {
    SYSTEM_INFO.get_or_init(|| {
        let mut info = [0i8; 64];
        let mut size = std::mem::size_of_val(&info);
        let mib = [6i32, 0i32]; // CTL_HW, HW_MODEL

        let ret = unsafe {
            libc::sysctl(
                mib.as_ptr(),
                mib.len() as u32,
                info.as_mut_ptr(),
                &mut size,
                std::ptr::null_mut(),
                0,
            )
        };

        if ret == 0 && size > 0 {
            let model = unsafe {
                std::ffi::CStr::from_ptr(info.as_ptr() as *const std::ffi::c_char)
                    .to_string_lossy()
                    .to_string()
            };
            // Extract the arch from model string (e.g., "x86_64" from "MacBookPro17,1")
            let arch = if model.contains("ARM") || model.contains("arm") {
                "aarch64".to_string()
            } else {
                "x86_64".to_string()
            };
            ("OpenBSD".to_string(), arch)
        } else {
            ("OpenBSD".to_string(), "unknown".to_string())
        }
    })
}

pub fn platform_info() -> (&'static str, &'static str) {
    let info = get_system_info();
    (&info.0, &info.1)
}

use std::sync::OnceLock;

static SYSTEM_INFO: OnceLock<(String, String)> = OnceLock::new();

fn get_system_info() -> &'static (String, String) {
    SYSTEM_INFO.get_or_init(|| {
        // On Linux, use uname(2) to get machine architecture
        let mut utsname = unsafe { std::mem::zeroed() };
        let ret = unsafe { libc::uname(&mut utsname) };

        if ret == 0 {
            let arch = unsafe {
                std::ffi::CStr::from_ptr(utsname.machine.as_ptr())
                    .to_string_lossy()
                    .to_string()
            };
            ("Linux".to_string(), arch)
        } else {
            ("Linux".to_string(), "unknown".to_string())
        }
    })
}

pub fn platform_info() -> (&'static str, &'static str) {
    let info = get_system_info();
    (&info.0, &info.1)
}

