use std::sync::OnceLock;

static SYSTEM_INFO: OnceLock<(String, String)> = OnceLock::new();

fn get_system_info() -> &'static (String, String) {
    SYSTEM_INFO.get_or_init(|| {
        let mut info = unsafe { std::mem::zeroed() };
        // GetSystemInfo retrieves information about the system-wide hardware
        unsafe { windows::Win32::System::SystemInformation::GetSystemInfo(&mut info as *mut _ as *mut _) };

        // Determine architecture based on processor architecture
        let arch = match unsafe { info.wProcessorArchitecture } {
            0 => "x86",
            5 => "ARM",
            6 => "x86_64",
            9 => "ARM64",
            _ => "unknown",
        };

        ("Windows".to_string(), arch.to_string())
    })
}

pub fn platform_info() -> (&'static str, &'static str) {
    let info = get_system_info();
    (&info.0, &info.1)
}

use std::sync::OnceLock;

static PLATFORM: OnceLock<String> = OnceLock::new();

fn get_platform() -> &'static String {
    PLATFORM.get_or_init(|| {
        format!(
            "unknown (target_os={})",
            env!("TARGET_OS_FALLBACK")
        )
    })
}

pub fn platform_info() -> (&'static str, &'static str) {
    ("unknown", get_platform())
}

